async function api(path,data){const r=await fetch('/api/orders/'+path,data===undefined?{credentials:'same-origin'}:{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});let d;try{d=await r.json();}catch{throw Error('The server returned an unreadable response.');}if(!r.ok)throw Error(d.error||'Action failed.');return d;}
async function act(name,data={}){const id=S.order.id,d=await api(id+'/'+name,{revision:S.order.revision,...data});if(d.id===id)S.order=d;await orders(false);render();return d;}
