async function orders(first=true){const d=await api('admin?'+new URLSearchParams({page:String(S.page),search:S.search,status:S.filter}));$('#signin').hidden=true;$('#orders-view').hidden=S.view!=='orders';$('#order-count').textContent=d.total;$('#page-label').textContent=d.total?S.page+' / '+Math.ceil(d.total/d.pageSize):'0 orders';$('#prev-page').disabled=S.page<=1;$('#next-page').disabled=S.page*d.pageSize>=d.total;const list=$('#order-list');list.replaceChildren();if(!d.orders.length)P(list,'No orders match this view.');for(const o of d.orders){const b=E('button',undefined,'order-row'+(o.id===S.order?.id?' selected':''));b.append(E('strong',o.story?.title||'Untitled book'),E('small',o.email+' · '+o.label),E('em',o.status.replaceAll('_',' ')+' · '+pounds(o.amount)));b.onclick=()=>void select(o.id);list.append(b);}if(first&&!S.order&&d.orders.length)await select(d.orders[0].id);if(!S.busy){const gaps=Object.entries(d.connections).filter(([k,v])=>!v&&['payments','gateway','webhook','printer','email','enabled'].includes(k)).map(([k])=>k);msg(gaps.length?'Live release needs: '+gaps.join(', ')+'.':'Owner workspace ready. Payment never sends a book to print.'+(d.connections.taxConfirmed?'':' Tax setup is marked unconfirmed.'));}}
