function render(){const o=S.order,root=$('#order-workspace');if(!o)return;root.replaceChildren();const head=E('div',undefined,'detail-header'),title=E('div');title.append(E('span',o.id,'mini-label'),E('h2',o.story?.title||'Untitled book'),E('p',o.email+' · '+o.label+' · '+pounds(o.amount)+' · version '+o.contentVersion));head.append(title,E('span',o.status.replaceAll('_',' '),'status-pill'+(['approved','submitted'].includes(o.status)?' good':'')));root.append(head);const tabs=E('nav',undefined,'detail-tabs');for(const [key,label] of [['book','Book pages'],['proof','Proof and print'],['customer','Customer'],['versions','Versions'],['activity','Activity']]){const b=E('button',label,S.tab===key?'active':'');b.onclick=()=>{S.tab=key;render();};tabs.append(b);}root.append(tabs);const grid=E('div',undefined,'detail-grid'),main=E('div'),side=E('aside',undefined,'side');grid.append(main,side);root.append(grid);({book:book,proof:proof,customer:customer,versions:versions,activity:activity})[S.tab](o,main);sidebar(o,side);}
async function finish(id){while(true){S.order=await api(id);const slots=[['cover',S.order.art?.cover],...(S.order.art?.scenes||[]).map((key,i)=>[i,key])],missing=slots.find(([,key])=>!key);if(!missing)break;msg('Drawing '+(missing[0]==='cover'?'cover':'scene '+(missing[0]+1))+'…');await act('illustrate',{page:missing[0],replace:false});}msg('Building the new PDF proof…');await act('make-proof');S.tab='proof';render();msg('New PDF ready. Review it before emailing the customer.');}
function book(o,root){const intro=box(root,'Full book review'),count=Number(!!o.art?.cover)+(o.art?.scenes||[]).filter(Boolean).length;P(intro,'Review every page and image. Changes clear earlier approvals.');P(intro,count+' of 11 illustrations ready · '+(o.artAttempts||0)+' of '+(o.artBudget||22)+' paid illustration requests used.','progress-text');if(o.generationError)P(intro,o.generationError,'alert error');if(o.status==='generating'){P(intro,'Generation is in progress. Refresh shortly.','alert');button(intro,'Recover stuck generation',async()=>{if(confirm('Only continue if it has been stuck for five minutes and you checked provider usage.'))await act('recover-generation');});}const budget=input(intro,'Illustration request limit',o.artBudget||22);budget.type='number';budget.min=String(o.artAttempts||0);budget.max='44';button(intro,'Update limit',async()=>{await act('set-art-budget',{artBudget:Number(budget.value),confirm:true});msg('Limit updated.');},editable(o),'secondary');const note=input(intro,'Notes for a full rewrite (optional)','',true);button(intro,'Regenerate the whole book',async()=>{if(!confirm('Rewrite 10 scenes, redraw 11 images and build a new proof? This uses paid AI requests and clears approvals.'))return;msg('Rewriting the story…');await act('regenerate-book',{note:note.value,confirm:true});await finish(o.id);},editable(o)&&(o.artBudget||22)-(o.artAttempts||0)>=11&&(o.storyRewriteAttempts||0)<6,'danger');button(intro,'Generate missing artwork and proof',async()=>{if(confirm('Generate every missing image and a proof? Each image uses a paid AI request.'))await finish(o.id);},editable(o)&&count<11,'secondary');const cover=box(root,'Cover');if(o.art?.cover)link(cover,'View cover artwork',art(o,o.art.cover));else P(cover,'Cover art missing.');button(cover,o.art?.cover?'Redraw cover':'Draw cover',async()=>{if(confirm('Use one paid illustration request and clear the current proof?'))await act('illustrate',{page:'cover',replace:!!o.art?.cover});},editable(o)&&(o.artAttempts||0)<(o.artBudget||22));(o.story?.spreads||[]).forEach((page,i)=>{const s=box(root,'Scene '+(i+1)),row=E('div',undefined,'story-card'),key=o.art?.scenes?.[i];if(key){const image=E('img',undefined,'story-image');image.src=art(o,key);image.alt='Scene '+(i+1)+' illustration';row.append(image);}else row.append(E('div','Image missing','image-empty'));const content=E('div');row.append(content);s.append(row);P(content,page.text,'story-copy');P(content,'Illustration direction: '+page.image_scene,'story-scene');const text=input(content,'Story text',page.text,true),scene=input(content,'Illustration direction',page.image_scene,true),redraw=check(content,'Clear this illustration so it can be redrawn');button(content,'Save this page',async()=>{await act('edit-page',{page:i,text:text.value,imageScene:scene.value,redrawImage:redraw.checked});msg('Page saved as a new version.');},editable(o),'secondary');const guidance=input(content,'Rewrite guidance (optional)');button(content,'Regenerate this page',async()=>{if(confirm('Use one paid story request and clear the current proof?')){await act('rewrite-page',{page:i,note:guidance.value,redrawImage:redraw.checked,confirm:true});msg('Page regenerated. Review before building the proof.');}},editable(o)&&(o.storyRewriteAttempts||0)<6);button(content,key?'Redraw this image':'Draw this image',async()=>{if(confirm('Use one paid illustration request and clear the current proof?'))await act('illustrate',{page:i,replace:!!key});},editable(o)&&(o.artAttempts||0)<(o.artBudget||22),'secondary');});}
