function versions(o,root){const s=box(root,'Saved content versions');P(s,'Current version '+o.contentVersion+'. Restoring an earlier version clears the proof and approvals.');if(!(o.history||[]).length)P(s,'No earlier versions saved yet.');for(const v of [...(o.history||[])].reverse()){const row=E('div',undefined,'version-row');row.append(E('strong','Version '+v.version+' · '+v.kind.replaceAll('_',' ')),E('small',when(v.at)+' · '+(v.actor||'system')));button(row,'Restore version '+v.version,async()=>{if(confirm('Restore version '+v.version+'? The current version will be saved and approvals cleared.')){await act('restore-version',{version:v.version,confirm:true});msg('Version restored. Rebuild the proof.');}},editable(o),'secondary');s.append(row);}}
