async function quotes(){try{const d=await api('admin-quotes');$('#quoted-total').textContent=d.totals.quotedNotBought;$('#saved-total').textContent=d.totals.savedUnpaid;$('#eligible-total').textContent=d.totals.offerEligible;const list=$('#quote-list');list.replaceChildren();let shown=0;for(const q of d.quotes){if(q.has_paid)continue;shown++;const row=E('tr');for(const value of [q.email,when(q.last_shown_at),q.size+' · '+pounds(q.price_pence),q.last_order_status||'No saved order',q.email_status||(q.offer_consent_at?'Opted in':'No offer permission')])row.append(E('td',value));const actions=E('td');if(q.saved_order_id)button(actions,'Open order',async()=>{view('orders');await select(q.saved_order_id);},true,'secondary');if(q.eligible)button(actions,'Send £3 offer',async()=>{if(!confirm('Send one £3 discount email to '+q.email+'? The code lasts 7 days.'))return;const result=await api('admin-send-offer',{email:q.email,discountPence:300,confirm:true});msg(result.message,!result.accepted);await quotes();});row.append(actions);list.append(row);}if(!shown){const row=E('tr'),cell=E('td','No tracked quotes yet.');cell.colSpan=6;row.append(cell);list.append(row);}}catch(e){msg(e.message,true);}}
